 void hide(){top.setVisibility(View.GONE);PlayerGlass.showDim(dim,false);bottom.setVisibility(View.GONE);if(center!=null)center.setVisibility(View.GONE);side.setVisibility(View.GONE);subtitlePosition();}
 void subtitlePosition(){FrameLayout.LayoutParams p=(FrameLayout.LayoutParams)sub.getLayoutParams();p.bottomMargin=bottom.getVisibility()==View.VISIBLE?Math.max(dp(150),bottom.getHeight()+dp(22)):dp(20);sub.setLayoutParams(p);}
 void update(){VideoFullscreen.padMedia3(a,top,bottom,side);PlayerMedia.tick(a);SubtitleStyle.apply(a,sub,bottom.getVisibility()==View.VISIBLE);next.tick();if(PlaybackPrefs.showBufferSpeed(prefs)&&a.video.player!=null){long bps=androidx.media3.exoplayer.upstream.DefaultBandwidthMeter.getSingletonInstance(a).getBitrateEstimate();PlayerSwitches.BUFFER.put(a,"网络估计 "+(bps/8192)+" KB/s · 已缓冲 "+a.video.getBufferPercentage()+"%");}else PlayerSwitches.BUFFER.remove(a);if(!dragging){time.setText(PlayerGlassRules.clockText(a.video.getCurrentPosition()));String minus=PlayerGlass.remaining(a.video.getCurrentPosition(),a.video.getDuration(),a.video.speed(),System.currentTimeMillis(),null);if(!minus.equals(left.getText().toString()))left.setText(minus);if(a.video.getDuration()>0)seek.setProgress((int)((long)a.video.getCurrentPosition()*10000/a.video.getDuration()));seek.setSecondaryProgress(a.video.getBufferPercentage()*100);}PlayerGlass.paintPlay(a,play,a.video.wantsPlayback());if(center!=null&&center.getVisibility()==View.VISIBLE)PlayerGlass.applySeek(a,seekBack,play,seekFwd,!dragging&&PlayerGlass.seekVisible(center));rate.setText(PlaybackPrefs.speedLabel(a.video.speed()));rate.setTextColor(PlayerGlassRules.speedAccent(a.video.speed())?PlayerTheme.playbackAccent(CinemaTheme.gold(a)):PlayerGlassRules.QUIET_TEXT);if(!dragging&&!holding&&!CinemaMenu.isOpen(a)&&!hasControlFocus()&&SystemClock.elapsedRealtime()>hideAt)hide();PlayerSwitches.applyRefresh(a);Media3Sound.tick(a);PlayerOverlay.statusLine(a);DanmuController.attach(a);DanmuController.tick(a);}
 boolean touch(MotionEvent e){remoteActive=false;
  if(e.getActionMasked()==MotionEvent.ACTION_DOWN){downX=e.getX();downY=e.getY();sliding=false;downVolume=audio==null?0:audio.getStreamVolume(AudioManager.STREAM_MUSIC);downBrightness=a.getWindow().getAttributes().screenBrightness;if(downBrightness<0)downBrightness=.5f;}
  if(!locked)scale.onTouchEvent(e);gestures.onTouchEvent(e);
  if(!locked&&e.getPointerCount()==1&&!holding&&e.getActionMasked()==MotionEvent.ACTION_MOVE){float delta=(downY-e.getY())/Math.max(1,a.video.getHeight());if(Math.abs(e.getY()-downY)>dp(24)&&Math.abs(e.getY()-downY)>Math.abs(e.getX()-downX)){sliding=true;if(downX<a.video.getWidth()/2f){WindowManager.LayoutParams p=a.getWindow().getAttributes();p.screenBrightness=Math.max(.02f,Math.min(1f,downBrightness+delta));a.getWindow().setAttributes(p);PlayerSwitches.saveBrightness(a);LevelHud.show(a,root,true,Math.round(p.screenBrightness*100),100);}else if(audio!=null){int max=audio.getStreamMaxVolume(AudioManager.STREAM_MUSIC);int vol=Math.max(0,Math.min(max,downVolume+Math.round(delta*max)));audio.setStreamVolume(AudioManager.STREAM_MUSIC,vol,0);LevelHud.show(a,root,false,max<=0?0:Math.round(vol*100f/max),100);}}}
  if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL){if(holding){a.video.speed(heldRate);holding=false;}if(sliding){LevelHud.hideSoon(a,LevelHudMetrics.HOLD_MS);hideAt=SystemClock.elapsedRealtime()+5000;}}
  return true;
 }
 boolean hasControlFocus(){View focused=a.getCurrentFocus();return remoteActive&&focused!=null&&focused!=a.video&&focused.hasFocus();}
